--
-- Name: match_nodes(public.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.match_nodes(query_embedding public.vector, match_threshold double precision DEFAULT 0.0, match_count integer DEFAULT 50) RETURNS TABLE(id text, name text, type text, subtitle text, location text, url text, tags text[], metadata jsonb, similarity double precision)
    LANGUAGE sql
    AS $$
  SELECT id, name, type, subtitle, location, url, tags, metadata,
    1 - (embedding <=> query_embedding) AS similarity
  FROM nodes
  WHERE embedding IS NOT NULL
    AND 1 - (embedding <=> query_embedding) > match_threshold
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;


