    community_id text NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    joined_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    added_by text,
    private_meta jsonb DEFAULT '{}'::jsonb NOT NULL
);


ALTER TABLE public.user_communities OWNER TO postgres;

--
-- Name: value_share_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.value_share_requests (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    requester_id text NOT NULL,
    community_id text NOT NULL,
    node_id text NOT NULL,
    column_key text NOT NULL,
    column_name text NOT NULL,
    column_type text NOT NULL,
    value text,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewer_id text,
    reviewer_note text,
    reviewed_at timestamp(3) without time zone,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


ALTER TABLE public.value_share_requests OWNER TO postgres;

